    skyscrapers_level_medium: "Mittel (5x5)",
    skyscrapers_level_hard: "Schwer (6x6)",
    skyscrapers_generating: "Rätsel wird erstellt…",
    skyscrapers_hint: "Wähle ein Feld, dann eine Höhe.",
    skyscrapers_undone: "Zug rückgängig gemacht.",
    skyscrapers_win_title: "Gelöst!",
